CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(200) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY,user_id INT NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS brands (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,category VARCHAR(100) NOT NULL,brand VARCHAR(100) NOT NULL,price DECIMAL(12,2) NOT NULL,compare_price DECIMAL(12,2) DEFAULT 0,stock INT NOT NULL DEFAULT 0,color VARCHAR(50),fabric VARCHAR(100),badge VARCHAR(50),image VARCHAR(500),description TEXT,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id INT AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(50) UNIQUE NOT NULL,user_id BIGINT UNSIGNED NULL,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(30) NOT NULL,address VARCHAR(500) NOT NULL,city VARCHAR(100) NOT NULL,payment_method ENUM('cod','bank') NOT NULL,total DECIMAL(12,2) NOT NULL,shipping DECIMAL(12,2) NOT NULL,status ENUM('Pending','Confirmed','Shipped','Delivered','Cancelled') NOT NULL DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS order_items (id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,name VARCHAR(150) NOT NULL,quantity INT NOT NULL,price DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS login_attempts (attempt_key CHAR(64) PRIMARY KEY,attempts INT NOT NULL DEFAULT 0,window_start DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS store_settings (id INT PRIMARY KEY,cod_enabled BOOLEAN NOT NULL DEFAULT TRUE,bank_enabled BOOLEAN NOT NULL DEFAULT FALSE,card_enabled BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT IGNORE INTO store_settings (id,cod_enabled,bank_enabled,card_enabled) VALUES (1,TRUE,FALSE,FALSE);
